FIST = 1.0                     # 0 = open hands ... 1 = full fists
OPEN_FADE = 0.2                # seconds the hands take to open / close around the clap
OPEN_WINDOWS = []  # seconds of the reference clip where hands are OPEN (the clap). [] = fists always

