# SETUP
# ----------------------------------------------------------------------------
rig = bpy.data.objects.get(ARMATURE_NAME)
if rig is None or rig.type != 'ARMATURE':
    rig = next((o for o in bpy.data.objects if o.type == 'ARMATURE'), None)
if rig is None:
    raise RuntimeError("No armature found. Open the file that contains your MPFB character.")

if bpy.context.object is not None and bpy.context.object.mode != 'OBJECT':
    bpy.ops.object.mode_set(mode='OBJECT')
bpy.ops.object.select_all(action='DESELECT')
rig.select_set(True)
bpy.context.view_layer.objects.active = rig
bpy.ops.object.mode_set(mode='POSE')

bones = rig.data.bones
pbones = rig.pose.bones

needed = ["root", "spine05", "spine01", "head", "foot.L", "foot.R", "upperarm01.L", "upperarm01.R",
          "lowerarm01.L", "lowerarm01.R", "wrist.L", "wrist.R", "upperleg01.L", "lowerleg01.L",
          "upperleg01.R", "lowerleg01.R", "finger2-1.L", "finger5-1.L"]
missing = [n for n in needed if n not in bones]
if missing:
    raise RuntimeError("These bones were not found on %s: %s" % (rig.name, missing))

lateral = 1.0 if bones["upperarm01.L"].head_local.x > 0 else -1.0          # character's left = +X ?
forward = 1.0 if bones["foot.L"].tail_local.y > bones["foot.L"].head_local.y else -1.0   # front = +Y ?
SIDE_X = {"L": lateral, "R": -lateral}


def DV(v):
    """dancer (left, forward, up)  ->  armature axes"""
    return Vector((lateral * v[0], forward * v[1], v[2]))


R3 = {b.name: b.matrix_local.to_3x3() for b in bones}
REL = {b.name: b.parent.matrix_local.inverted() @ b.matrix_local for b in bones if b.parent}


def depth(b):
    n = 0
    while b.parent:
        b = b.parent
        n += 1
    return n


def ordered(names):
    found = [bones[n] for n in names if n in bones]
    found.sort(key=depth)
    return [b.name for b in found]


SPINE = ordered(["spine01", "spine02", "spine03", "spine04", "spine05"])
HEAD_CHAIN = ordered(["neck01", "neck02", "neck03", "head"])
FINGERS = {s: [["finger%d-%d.%s" % (f, k, s) for k in (1, 2, 3)] for f in (1, 2, 3, 4, 5)] for s in ("L", "R")}
FINGERS = {s: [[n for n in chain if n in bones] for chain in FINGERS[s]] for s in FINGERS}


def seg(a, b):
    return bones[b].head_local - bones[a].head_local


ARM = {}
for s in ("L", "R"):
    up, fo, wr = "upperarm01.%s" % s, "lowerarm01.%s" % s, "wrist.%s" % s
    ARM[s] = dict(up=up, fo=fo, wr=wr, vE=seg(up, fo), vW=seg(fo, wr))
    ARM[s]["a"], ARM[s]["b"] = ARM[s]["vE"].length, ARM[s]["vW"].length
    ix, pk = "finger2-1.%s" % s, "finger5-1.%s" % s
    mid = (bones[ix].head_local + bones[pk].head_local) * 0.5
    hd = (mid - bones[wr].head_local).normalized()
    sd = (bones[ix].head_local - bones[pk].head_local)
    ARM[s]["F"] = Matrix([hd, (sd - hd * sd.dot(hd)).normalized(), hd.cross((sd - hd * sd.dot(hd)).normalized())]).transposed()

LEG = {}
for s in ("L", "R"):
    LEG[s] = dict(up="upperleg01.%s" % s, kn="lowerleg01.%s" % s, ft="foot.%s" % s,
                  vK=seg("upperleg01.%s" % s, "lowerleg01.%s" % s), vA=seg("lowerleg01.%s" % s, "foot.%s" % s))
    LEG[s]["a"], LEG[s]["b"] = LEG[s]["vK"].length, LEG[s]["vA"].length
    LEG[s]["ankle0"] = bones["foot.%s" % s].head_local.copy()

ARM_SCALE = (ARM["L"]["a"] + ARM["L"]["b"] + ARM["R"]["a"] + ARM["R"]["b"]) / 2.0 / ARM_LEN_DANCER

# finger curl axes (rotate each finger bone toward the palm)
CURL_AXIS = {}
for s in ("L", "R"):
    medial = Vector((-SIDE_X[s], 0.0, 0.0))
    for chain in FINGERS[s]:
        for n in chain:
            b = bones[n]
            f = (b.tail_local - b.head_local).normalized()
            nrm = medial - f * medial.dot(f)
            nrm.normalize()
            CURL_AXIS[n] = (R3[n].inverted() @ f.cross(nrm)).normalized()


# ----------------------------------------------------------------------------
# FORWARD KINEMATICS (pure maths)
#   pose_matrix = parent_pose @ (parent_rest^-1 @ rest) @ translation(local) @ rotation(local)
# ----------------------------------------------------------------------------
def limit_quat(q, max_deg, strength):
    if q.w < 0:
        q = Quaternion([-c for c in q])
    ang = q.angle * strength
    ang = min(ang, radians(max_deg))
    if q.angle < 1e-6:
        return q
    return Quaternion(q.axis, ang)


class Pose:
    def __init__(self):
        self.abs, self.rel, self.off = {}, {}, {}
        self.memo = {}

    def set_abs(self, name, rot3, limit=None):
        self.abs[name] = (rot3, limit)
        self.memo.clear()

    def set_rel(self, name, quat):
        self.rel[name] = quat
        self.memo.clear()

    def set_offset(self, name, vec):
        self.off[name] = vec
        self.memo.clear()

    def pose_of(self, b):
        m = self.memo.get(b.name)
        if m is not None:
            return m
        base = (self.pose_of(b.parent) @ REL[b.name]) if b.parent else b.matrix_local.copy()
        base3 = base.to_3x3()
        quat = None
        if b.name in self.abs:
            rot3, limit = self.abs[b.name]
            quat = (base3.inverted() @ rot3).to_quaternion()
            if limit:
                quat = limit_quat(quat, limit[0], limit[1])
        elif b.name in self.rel:
            quat = self.rel[b.name]
        t = base3.inverted() @ self.off[b.name] if b.name in self.off else Vector((0.0, 0.0, 0.0))
        if quat is None and b.name not in self.off:
            m = base
        else:
            q = quat if quat is not None else Quaternion((1, 0, 0, 0))
            m = base @ Matrix.Translation(t) @ q.to_matrix().to_4x4()
        self.memo[b.name] = m
        return m

    def head(self, name):
        return self.pose_of(bones[name]).translation.copy()

    def result(self, names):
        """local (location, quaternion) of the given bones"""
        self.memo.clear()
        out = {}
        for n in names:
            b = bones[n]
            base = (self.pose_of(b.parent) @ REL[n]) if b.parent else b.matrix_local.copy()
            base3 = base.to_3x3()
            quat = Quaternion((1, 0, 0, 0))
            if n in self.abs:
                rot3, limit = self.abs[n]
                quat = (base3.inverted() @ rot3).to_quaternion()
                if limit:
                    quat = limit_quat(quat, limit[0], limit[1])
            elif n in self.rel:
                quat = self.rel[n]
            t = base3.inverted() @ self.off[n] if n in self.off else Vector((0.0, 0.0, 0.0))
            out[n] = (t, quat)
        return out


def rot_y(a):
    return Matrix.Rotation(radians(a), 3, 'Y')


def rot_x(a):
    return Matrix.Rotation(radians(a), 3, 'X')


def rot_z(a):
    return Matrix.Rotation(radians(a), 3, 'Z')


def body_rot(sway, twist):
    """sway +: lean toward the character's left ; twist +: turn toward the character's left"""
    return rot_z(twist * lateral * -forward) @ rot_y(sway * lateral)


def head_rot(tilt, nod, turn):
    """tilt +: ear to the character's left ; nod +: look down ; turn +: look to the character's left"""
    return rot_z(turn * lateral * -forward) @ rot_x(nod * -forward) @ rot_y(tilt * lateral)


def two_bone(S, T, a, b, pole, fallback):
    d = T - S
    L = d.length
    Lc = min(max(L, abs(a - b) + 1e-3), (a + b) * 0.995)
    u = d.normalized() if L > 1e-6 else Vector((0, 0, -1))
    p = pole - u * pole.dot(u)
    if p.length < 1e-3:
        p = fallback - u * fallback.dot(u)
    p.normalize()
    cosA = (a * a + Lc * Lc - b * b) / (2 * a * Lc)
    sinA = sqrt(max(0.0, 1.0 - cosA * cosA))
    return S + u * (a * cosA) + p * (a * sinA), S + u * Lc


# ----------------------------------------------------------------------------
# PREPARE THE DATA
# ----------------------------------------------------------------------------
def smooth(t):
    t = max(0.0, min(1.0, t))
    return t * t * (3 - 2 * t)


def _gauss(arr, sigma):
    """zero-lag Gaussian smoothing of a (frames x columns) array, edges mirrored"""
    if sigma < 0.05:
        return arr.copy()
    rad = max(1, int(sigma * 3))
    k = np.exp(-0.5 * (np.arange(-rad, rad + 1) / sigma) ** 2)
    k /= k.sum()
    pad = np.pad(arr, ((rad, rad), (0, 0)), mode='reflect')
    return np.stack([np.convolve(pad[:, c], k, mode='valid') for c in range(arr.shape[1])], 1)


def _adaptive(arr, light, heavy, v0):
    """Quiet moments get heavy smoothing (this removes the jitter), fast hits keep light smoothing (keeps the snap)."""
    a = _gauss(arr, light * SMOOTHNESS)
    speed = _gauss(np.linalg.norm(np.gradient(a, axis=0), axis=1)[:, None], 1.5)[:, 0]
    w = np.clip(speed / v0, 0.0, 1.0)
    w = _gauss((w * w * (3 - 2 * w))[:, None], 3.0)[:, 0]               # the amount of smoothing changes gradually
    sigma = (heavy * (1.0 - w) + light * w) * SMOOTHNESS
    rad = int(3 * sigma.max()) + 1
    pad = np.pad(arr, ((rad, rad), (0, 0)), mode='reflect')
    out = np.empty_like(arr)
    for t in range(arr.shape[0]):                                       # a Gaussian whose width follows the motion speed
        r = max(1, int(3 * sigma[t]))
        k = np.exp(-0.5 * (np.arange(-r, r + 1) / max(sigma[t], 0.05)) ** 2)
        out[t] = (k[:, None] * pad[t + rad - r:t + rad + r + 1]).sum(0) / k.sum()
    return out


def _unit(v):
    return v / np.maximum(np.linalg.norm(v, axis=1, keepdims=True), 1e-6)


def smooth_data(data):
    d = np.array(data, dtype=float)
    if SMOOTHNESS <= 0:
        return d
    out = d.copy()
    for o in (0, 15):
        sh = _gauss(d[:, o:o + 3], 6.0 * SMOOTHNESS)
        pole = _adaptive(d[:, o + 3:o + 6] - d[:, o:o + 3], 2.0, 5.0, 0.010)   # where the elbow points
        out[:, o:o + 3] = sh
        out[:, o + 3:o + 6] = sh + pole
        out[:, o + 6:o + 9] = _adaptive(d[:, o + 6:o + 9], 0.8, 2.5, 0.012)    # wrists
        out[:, o + 9:o + 12] = _unit(_adaptive(d[:, o + 9:o + 12], 1.2, 3.5, 0.05))
        out[:, o + 12:o + 15] = _unit(_adaptive(d[:, o + 12:o + 15], 1.5, 4.0, 0.05))
    out[:, 30:33] = _adaptive(d[:, 30:33], 1.0, 3.0, 1.2)                      # head
    out[:, 33:35] = _adaptive(d[:, 33:35], 1.5, 4.0, 0.8)                      # shoulders
    out[:, 35:37] = _adaptive(d[:, 35:37], 2.0, 5.0, 0.5)                      # pelvis
    out[:, 37:39] = _adaptive(d[:, 37:39], 2.0, 5.0, 0.004)                    # hip sway / bounce
    out[:, 39:40] = _adaptive(d[:, 39:40], 3.0, 7.0, 0.004)                    # hip travel
    return out


# ONE MOVE: rest pose -> ease into the move -> the move (repeated) -> ease back to the rest pose
_all = smooth_data(DATA)[START_FRAME - 1:END_FRAME]
_rest = _all[0]
_seg = _all[MOVE_FIRST - 1:MOVE_LAST]
def _ease(p, q, n):
    return [list(p * (1.0 - smooth(k / float(n))) + q * smooth(k / float(n))) for k in range(1, n + 1)]
rows = [list(_rest) for _ in range(START_HOLD)]
rows += _ease(_rest, _seg[0], INTRO_FRAMES)
for _rep in range(REPEATS):
    if _rep > 0:
        rows += _ease(_seg[-1], _seg[0], LOOP_BLEND)
    rows += [list(r) for r in _seg]
rows += _ease(_seg[-1], _rest, OUTRO_FRAMES)
rows += [list(_rest) for _ in range(END_HOLD)]
NF = len(rows)
X0, _, Z0 = rows[0][37], rows[0][38], rows[0][39]


def open_amount(i):
    t = (START_FRAME - 1 + i) / 30.0
    v = 0.0
    for a, b in OPEN_WINDOWS:
        v = max(v, smooth((t - a) / OPEN_FADE) * smooth((b - t) / OPEN_FADE))
    return v


def root_params(i):
    r = rows[i]
    lat = max(-0.10, min(0.10, (r[37] - X0))) * SWAY_STRENGTH
    bob = max(-0.05, min(0.05, r[38])) * BOB_STRENGTH
    fwd = (Z0 - r[39]) * TRAVEL_STRENGTH
    return lat, bob, fwd


def root_pose(i):
    r = rows[i]
    lat, bob, fwd = root_params(i)
    P = Pose()
    P.set_offset("root", DV((lat, fwd, bob - KNEE_DROP)))
    tilt, yaw = r[35] * PELVIS_STRENGTH, r[36] * PELVIS_STRENGTH
    P.set_abs("root", body_rot(tilt, yaw) @ R3["root"])
    return P, DV((lat, fwd, 0.0))


# ----------------------------------------------------------------------------
# FOOT PLANNING (feet stay planted and step when the hips drift away)
# ----------------------------------------------------------------------------
def plan_feet():
    plan = {s: [] for s in ("L", "R")}
    planted = {s: LEG[s]["ankle0"].copy() for s in ("L", "R")}
    stepping = {s: None for s in ("L", "R")}
    settle_from = max(0, NF - END_HOLD - 2 * 16 - 4)               # from here the feet walk back to their start spots
    for i in range(NF):
        _, shift = root_pose(i)
        ahead = root_pose(min(NF - 1, i + 8))[1] - shift
        settling = i >= settle_from
        errs = {}
        for s in ("L", "R"):
            home = LEG[s]["ankle0"] + Vector((shift.x, shift.y, 0.0))
            errs[s] = (home - planted[s]).to_2d().length
        limit = 0.004 if settling else STEP_DISTANCE
        for s in ("L", "R"):
            other = "R" if s == "L" else "L"
            if stepping[s] is None and stepping[other] is None and errs[s] > limit and \
                    (errs[s] >= errs[other]):
                if settling:
                    home = LEG[s]["ankle0"]
                else:
                    home = LEG[s]["ankle0"] + Vector((shift.x + ahead.x * 0.6, shift.y + ahead.y * 0.6, 0.0))
                dist = (Vector((home.x, home.y, 0.0)) - Vector((planted[s].x, planted[s].y, 0.0))).length
                dur = max(STEP_FRAMES, int(ceil(dist / 0.025)))          # long steps take longer (never faster than ~0.75 m/s)
                stepping[s] = [i, planted[s].copy(), Vector((home.x, home.y, planted[s].z)), dur]
        for s in ("L", "R"):
            pos = planted[s].copy()
            if stepping[s] is not None:
                i0, a, b, dur = stepping[s]
                u = (i - i0) / float(dur)
                if u >= 1.0:
                    planted[s] = b.copy()
                    pos = b.copy()
                    stepping[s] = None
                else:
                    k = smooth(u)
                    pos = a * (1 - k) + b * k
                    pos.z = planted[s].z + 0.05 * sin(pi * u)
            plan[s].append(pos)
    for s in ("L", "R"):                                            # final frames: exactly where the feet began
        for i in range(max(0, NF - END_HOLD), NF):
            plan[s][i] = LEG[s]["ankle0"].copy()
    return plan


# ----------------------------------------------------------------------------
# SOLVE ONE FRAME
# ----------------------------------------------------------------------------
HAND_NAMES = []
for s in ("L", "R"):
    HAND_NAMES += [ARM[s]["up"], ARM[s]["fo"], ARM[s]["wr"]]
LEG_NAMES = []
for s in ("L", "R"):
    LEG_NAMES += [LEG[s]["up"], LEG[s]["kn"], LEG[s]["ft"]]
FINGER_NAMES = [n for s in ("L", "R") for chain in FINGERS[s] for n in chain]
KEYED = ["root"] + SPINE + HEAD_CHAIN + HAND_NAMES + (LEG_NAMES if USE_LEGS else []) + FINGER_NAMES


HAND_Y = {}


def solve_frame(i, feet):
    r = rows[i]
    P, _shift = root_pose(i)

    sway, twist = r[33] * TORSO_STRENGTH, r[34] * TORSO_STRENGTH
    tilt, nod, turn = r[30] * HEAD_STRENGTH, r[31] * HEAD_STRENGTH, r[32] * HEAD_STRENGTH
    q_id = Quaternion((1, 0, 0, 0))
    q_t = body_rot(sway, twist).to_quaternion()
    for k, name in enumerate(SPINE):
        P.set_abs(name, q_id.slerp(q_t, (k + 1) / len(SPINE)).to_matrix() @ R3[name])
    q_h = head_rot(tilt, nod, turn).to_quaternion()
    for k, name in enumerate(HEAD_CHAIN):
        P.set_abs(name, q_t.slerp(q_h, (k + 1) / len(HEAD_CHAIN)).to_matrix() @ R3[name])

    # ---- legs
    if USE_LEGS:
        for s in ("L", "R"):
            Lg = LEG[s]
            S = P.head(Lg["up"])
            side = 1.0 if s == "L" else -1.0
            fallback = Vector((SIDE_X[s] * 0.15, forward * 1.0, 0.0))
            E, A = two_bone(S, feet[s][i], Lg["a"], Lg["b"], fallback, fallback)
            P.set_abs(Lg["up"], Lg["vK"].rotation_difference(E - S).to_matrix() @ R3[Lg["up"]])
            P.set_abs(Lg["kn"], Lg["vA"].rotation_difference(A - E).to_matrix() @ R3[Lg["kn"]])
            P.set_abs(Lg["ft"], R3[Lg["ft"]])

    # ---- arms
    SL, SR = P.head(ARM["L"]["up"]), P.head(ARM["R"]["up"])
    Mc = (SL + SR) * 0.5
    targets = {}
    for s in ("L", "R"):
        A = ARM[s]
        arr = r[0:15] if s == "L" else r[15:30]
        sh_m, el_m, wr_m = Vector(arr[0:3]), Vector(arr[3:6]), Vector(arr[6:9])
        S = P.head(A["up"])
        W = Mc + DV(wr_m) * ARM_SCALE
        pole_m = DV(el_m - sh_m)
        u_m = DV(wr_m - sh_m).normalized()
        pole = pole_m - u_m * pole_m.dot(u_m)
        fallback = DV(Vector((0.4 * (1 if s == "L" else -1), -0.4, -1.0)))
        E, Wc = two_bone(S, W, A["a"], A["b"], pole, fallback)
        P.set_abs(A["up"], A["vE"].rotation_difference(E - S).to_matrix() @ R3[A["up"]])
        P.set_abs(A["fo"], A["vW"].rotation_difference(Wc - E).to_matrix() @ R3[A["fo"]])
        hd, sd = DV(Vector(arr[9:12])).normalized(), DV(Vector(arr[12:15]))
        y = (sd - hd * sd.dot(hd))
        # How the hand is twisted comes from the "across the hand" direction. When that direction lines up with
        # the hand direction it cannot be trusted, so the previous twist is kept (this removes the wrist snaps).
        conf = smooth((y.length - 0.2) / 0.4)
        prev = HAND_Y.get(s)
        if y.length > 1e-4:
            y = y.normalized()
        if prev is not None:
            yp = prev - hd * prev.dot(hd)
            if yp.length > 1e-3:
                yp.normalize()
                y = (y * conf + yp * (1.0 - conf)) if y.length > 1e-4 else yp
        if y.length > 1e-4:
            y.normalize()
            HAND_Y[s] = y.copy()
            Fm = Matrix([hd, y, hd.cross(y)]).transposed()
            P.set_abs(A["wr"], (Fm @ A["F"].inverted()) @ R3[A["wr"]], (WRIST_LIMIT, HAND_STRENGTH))
        targets[s] = Wc

    # ---- fingers (fist)
    close = FIST * (1.0 - open_amount(i))
    for s in ("L", "R"):
        for fi, chain in enumerate(FINGERS[s]):
            angles = THUMB_CURL if fi == 0 else FINGER_CURL
            for k, name in enumerate(chain):
                if fi == 0 and name in THUMB_TUCK:
                    P.set_rel(name, Quaternion((1.0, 0.0, 0.0, 0.0)).slerp(Quaternion(THUMB_TUCK[name]), close))
                else:
                    P.set_rel(name, Quaternion(CURL_AXIS[name], radians(angles[k] * close)))

    return P.result(KEYED), targets


# ----------------------------------------------------------------------------
# BUILD THE ANIMATION
# ----------------------------------------------------------------------------
rig.animation_data_clear()
for pb in pbones:
    pb.location = (0.0, 0.0, 0.0)
    pb.rotation_quaternion = (1.0, 0.0, 0.0, 0.0)
    pb.rotation_euler = (0.0, 0.0, 0.0)
    pb.scale = (1.0, 1.0, 1.0)
for name in KEYED:
    pbones[name].rotation_mode = 'QUATERNION'

feet = plan_feet() if USE_LEGS else None
check = {}
solved = []
mid = NF // 2
for i in range(NF):
    res, tg = solve_frame(i, feet)
    solved.append(res)
    if i == mid:
        check = (1 + i, tg)


def _angle(q1, q2):
    return 2.0 * degrees(acos(min(1.0, abs(q1.dot(q2)))))


POST_SIGMA = {"wrist": 1.5, "lowerarm": 0.8, "upperarm": 0.8}   # extra smoothing of the joint angles (frames)

# keep quaternion signs continuous, then remove one-frame glitches (a frame that jumps away and straight back)
seq = {}
fixed = 0
for name in KEYED:
    qs, prev = [], None
    for i in range(NF):
        q = solved[i][name][1]
        if prev is not None and prev.dot(q) < 0:
            q = Quaternion([-c for c in q])
        qs.append(q.copy())
        prev = q
    for i in range(1, NF - 1):
        m = qs[i - 1].slerp(qs[i + 1], 0.5)
        d_bm, d_ac = _angle(qs[i], m), _angle(qs[i - 1], qs[i + 1])
        if d_bm > 8.0 and d_bm > 1.5 * d_ac:
            qs[i] = m
            fixed += 1
    for key, sig in POST_SIGMA.items():          # light extra smoothing of the arm joint angles
        if name.startswith(key) and SMOOTHNESS > 0:
            keep0, keepN = qs[0].copy(), qs[-1].copy()
            arr = _gauss(np.array([[q.w, q.x, q.y, q.z] for q in qs]), sig * SMOOTHNESS)
            arr /= np.linalg.norm(arr, axis=1, keepdims=True)
            qs = [Quaternion(tuple(float(c) for c in a)) for a in arr]
            qs[0], qs[-1] = keep0, keepN         # first and last pose stay exactly identical
    seq[name] = qs

for i in range(NF):
    frame = 1 + i
    for name in KEYED:
        pb = pbones[name]
        pb.rotation_quaternion = seq[name][i]
        pb.keyframe_insert("rotation_quaternion", frame=frame)
        if name == "root":
            pb.location = solved[i][name][0]
            pb.keyframe_insert("location", frame=frame)

scene = bpy.context.scene
scene.render.fps = FPS
scene.frame_start = 1
scene.frame_end = NF
scene.frame_set(1)

if rig.animation_data and rig.animation_data.action:
    try:
        rig.animation_data.action.name = "Dance"
    except Exception:
        pass

# ----------------------------------------------------------------------------
# SELF-CHECK: do the wrists end up where they were meant to?
# ----------------------------------------------------------------------------
worst = None
try:
    scene.frame_set(check[0])
    bpy.context.view_layer.update()
    worst = 0.0
    for s in ("L", "R"):
        got = pbones[ARM[s]["wr"]].head
        worst = max(worst, (got - check[1][s]).length)
    scene.frame_set(1)
    bpy.context.view_layer.update()
    first_pose = {n: pbones[n].matrix.copy() for n in KEYED}
    scene.frame_set(NF)
    bpy.context.view_layer.update()
    ends_differ = max((pbones[n].matrix.translation - first_pose[n].translation).length for n in KEYED)
    scene.frame_set(1)
except Exception as exc:
    ends_differ = None
    print("Self-check skipped:", exc)

print("Dance created: %d frames. Worst wrist error %s m. Start/end pose difference %s m. Glitches fixed: %d"
      % (NF, worst, ends_differ, fixed))


def _done(self, context):
    self.layout.label(text="Dance created: frames 1-%d. Press Spacebar to play." % NF)
    if ends_differ is not None and ends_differ > 0.01:
        self.layout.label(text="Warning: first and last pose differ by %.0f cm - tell Claude." % (ends_differ * 100))
    if worst is not None and worst > 0.03:
        self.layout.label(text="Warning: wrists are %.0f cm off - tell Claude." % (worst * 100))


try:
    bpy.context.window_manager.popup_menu(_done, title="Dance created", icon='INFO')
except Exception:
    pass